mapper.select:
SELECT f.*, s.real_name AS supervisor_real_name, s.phone AS supervisor_phone, gm.real_name AS grid_member_name, gp.name AS province_name, gc.name AS city_name FROM aqi_feedback f LEFT JOIN supervisor s ON f.supervisor_id = s.id LEFT JOIN grid_member gm ON f.grid_member_id = gm.id LEFT JOIN grid_province gp ON f.province_id = gp.id LEFT JOIN grid_city gc ON f.city_id = gc.id
AND f.status = #{status}
AND f.province_id = #{provinceId}
AND f.city_id = #{cityId}
ORDER BY f.create_time DESC
